package main

import (
	_ "embed"
	"encoding/json"
	"fmt"
)

// accept_acs.json links each acceptance case to the Story ACs (Redmine Epic
// #22947, AC01-AC50) it checks, with each AC's unit-test coverage. It is
// generated by coverage/gen_accept_acs.py from coverage/accept_map.py and the
// coverage page's data; regenerate it with the coverage pages.
//
//go:embed accept_acs.json
var acceptACsJSON []byte

// caseAC is one Story AC an acceptance case checks.
type caseAC struct {
	AC     string       `json:"ac"`
	Story  string       `json:"story"`
	Title  string       `json:"title"`
	MM     string       `json:"mm"`
	Status string       `json:"status"` // coverage: covered, partial, none, not_built
	Tests  []caseACTest `json:"tests"`
}

type caseACTest struct {
	Name  string `json:"name"`
	Repo  string `json:"repo"`
	File  string `json:"file"`
	Line  int    `json:"line,omitempty"`
	State string `json:"state"` // pass, fail, unknown (last go test run)
}

type acceptACs struct {
	Generated string              `json:"generated"`
	Cases     map[string][]caseAC `json:"cases"`
}

// loadAcceptACs reads the embedded links and checks they name exactly the
// cases the page has, so a renamed or new case cannot silently lose them.
func loadAcceptACs(cases []acceptCase) (acceptACs, error) {
	var links acceptACs
	if err := json.Unmarshal(acceptACsJSON, &links); err != nil {
		return links, fmt.Errorf("accept_acs.json: %w", err)
	}
	known := map[string]bool{}
	for _, c := range cases {
		known[c.ID] = true
		if _, ok := links.Cases[c.ID]; !ok {
			return links, fmt.Errorf("accept_acs.json has no entry for case %s: add it to coverage/accept_map.py", c.ID)
		}
	}
	for id := range links.Cases {
		if !known[id] {
			return links, fmt.Errorf("accept_acs.json names unknown case %s", id)
		}
	}
	return links, nil
}
